#### REQ-IFR-INT-003-001: AWS Lambda for Stateless Transformation

**Status**: Recommended
**Rationale**: Serverless transformation for simple, event-driven use cases

**Requirements**:
- Use Lambda for stateless transformations (mapping, filtering, enrichment)
- Configure Lambda with MSK event source mapping
- Use Python 3.12 or Node.js 20 runtime
- Configure reserved concurrency based on throughput requirements
- Set timeout to 30 seconds maximum for transformation functions

**Implementation**:
```hcl
# Lambda Function for Event Transformation
resource "aws_lambda_function" "event_transformer" {
  filename      = "event_transformer.zip"
  function_name = "eaas-event-transformer-${var.environment}"
  role          = aws_iam_role.lambda_transformer.arn
  handler       = "index.handler"
  runtime       = "python3.12"
  timeout       = 30
  memory_size   = 512

  # Reserved concurrency for throughput control
  reserved_concurrent_executions = var.lambda_concurrency

  # VPC Configuration for MSK access
  vpc_config {
    subnet_ids         = var.private_subnet_ids
    security_group_ids = [aws_security_group.lambda_transformer.id]
  }

  environment {
    variables = {
      KAFKA_BROKERS       = module.msk_cluster.bootstrap_brokers_tls
      OUTPUT_TOPIC        = "eaas.transformed.events"
      SCHEMA_REGISTRY_URL = var.schema_registry_url
      DLQ_TOPIC          = "eaas.transformation.dlq"
      LOG_LEVEL          = var.log_level
    }
  }

  # Layers for common dependencies
  layers = [
    aws_lambda_layer_version.kafka_client.arn,
    aws_lambda_layer_version.schema_validator.arn
  ]

  # X-Ray Tracing
  tracing_config {
    mode = "Active"
  }

  tags = merge(var.common_tags, {
    Name      = "eaas-event-transformer-${var.environment}"
    Component = "transformation"
  })
}

# MSK Event Source Mapping
resource "aws_lambda_event_source_mapping" "msk_trigger" {
  event_source_arn  = module.msk_cluster.arn
  function_name     = aws_lambda_function.event_transformer.arn
  topics            = ["eaas.raw.events"]
  starting_position = "LATEST"

  # Batch configuration
  batch_size                         = 100
  maximum_batching_window_in_seconds = 5

  # Error handling
  function_response_types = ["ReportBatchItemFailures"]

  # Scaling configuration
  scaling_config {
    maximum_concurrency = var.lambda_max_concurrency
  }

  # Dead letter configuration
  destination_config {
    on_failure {
      destination_arn = aws_sqs_queue.lambda_dlq.arn
    }
  }

  # Self-managed Kafka configuration
  self_managed_kafka_event_source_config {
    consumer_group_id = "eaas-lambda-transformer-${var.environment}"
  }
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_transformer" {
  name = "eaas-lambda-transformer-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

# IAM Policy for Lambda
resource "aws_iam_role_policy" "lambda_transformer" {
  name = "lambda-transformer-policy"
  role = aws_iam_role.lambda_transformer.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:DescribeCluster",
          "kafka-cluster:ReadData",
          "kafka-cluster:WriteData"
        ]
        Resource = module.msk_cluster.arn
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Effect = "Allow"
        Action = [
          "xray:PutTraceSegments",
          "xray:PutTelemetryRecords"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "sqs:SendMessage"
        ]
        Resource = aws_sqs_queue.lambda_dlq.arn
      }
    ]
  })
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "lambda_transformer" {
  name              = "/aws/lambda/eaas-event-transformer-${var.environment}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.logs.arn

  tags = var.common_tags
}

# Security Group for Lambda
resource "aws_security_group" "lambda_transformer" {
  name_prefix = "eaas-lambda-transformer-${var.environment}-"
  description = "Security group for Lambda event transformer"
  vpc_id      = var.vpc_id

  egress {
    description = "MSK access"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "HTTPS for Schema Registry"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "eaas-lambda-transformer-${var.environment}"
  })
}

# Lambda Layer for Kafka Client
resource "aws_lambda_layer_version" "kafka_client" {
  filename   = "kafka_client_layer.zip"
  layer_name = "kafka-client-python312"

  compatible_runtimes = ["python3.12"]

  description = "Kafka client libraries for Python 3.12"
}

# Lambda Layer for Schema Validation
resource "aws_lambda_layer_version" "schema_validator" {
  filename   = "schema_validator_layer.zip"
  layer_name = "schema-validator-python312"

  compatible_runtimes = ["python3.12"]

  description = "Schema Registry and Avro validation libraries"
}

# Dead Letter Queue
resource "aws_sqs_queue" "lambda_dlq" {
  name                      = "eaas-lambda-transformer-dlq-${var.environment}"
  message_retention_seconds = 1209600  # 14 days

  tags = var.common_tags
}
```

