#### REQ-IFR-INT-003-005: AWS Step Functions for Orchestrated Transformations

**Status**: Recommended
**Rationale**: Multi-step transformation workflows with error handling and retries

**Requirements**:
- Use Step Functions Standard Workflows for long-running transformations
- Use Step Functions Express Workflows for high-volume, short-duration transformations
- Configure error handling with exponential backoff
- Integrate with Lambda, Glue, and ECS tasks
- Enable X-Ray tracing for workflow visibility

**Implementation**:
```hcl
# Step Functions State Machine for Multi-Step Transformation
resource "aws_sfn_state_machine" "event_transformation_workflow" {
  name     = "eaas-transformation-workflow-${var.environment}"
  role_arn = aws_iam_role.step_functions.arn

  # Enable X-Ray tracing
  tracing_configuration {
    enabled = true
  }

  # State machine definition (ASL - Amazon States Language)
  definition = jsonencode({
    Comment = "Event transformation workflow with validation, enrichment, and delivery"
    StartAt = "ValidateEvent"

    States = {
      # Step 1: Validate Event Schema
      ValidateEvent = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.schema_validator.arn
          Payload = {
            "event.$" = "$"
          }
        }
        ResultPath = "$.validation"
        Retry = [
          {
            ErrorEquals     = ["Lambda.ServiceException", "Lambda.AWSLambdaException", "Lambda.SdkClientException"]
            IntervalSeconds = 2
            MaxAttempts     = 3
            BackoffRate     = 2.0
          }
        ]
        Catch = [
          {
            ErrorEquals = ["States.ALL"]
            ResultPath  = "$.error"
            Next        = "ValidationFailed"
          }
        ]
        Next = "CheckValidation"
      }

      # Step 2: Check Validation Result
      CheckValidation = {
        Type = "Choice"
        Choices = [
          {
            Variable      = "$.validation.Payload.valid"
            BooleanEquals = true
            Next          = "EnrichEvent"
          }
        ]
        Default = "ValidationFailed"
      }

      # Step 3: Enrich Event with External Data
      EnrichEvent = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.event_enricher.arn
          Payload = {
            "event.$" = "$.event"
          }
        }
        ResultPath = "$.enriched"
        Retry = [
          {
            ErrorEquals     = ["Lambda.ServiceException", "Lambda.AWSLambdaException", "Lambda.SdkClientException"]
            IntervalSeconds = 2
            MaxAttempts     = 3
            BackoffRate     = 2.0
          }
        ]
        Catch = [
          {
            ErrorEquals = ["States.ALL"]
            ResultPath  = "$.error"
            Next        = "EnrichmentFailed"
          }
        ]
        Next = "ParallelTransformation"
      }

      # Step 4: Parallel Transformation for Multiple Formats
      ParallelTransformation = {
        Type = "Parallel"
        Branches = [
          {
            StartAt = "TransformToAvro"
            States = {
              TransformToAvro = {
                Type     = "Task"
                Resource = "arn:aws:states:::lambda:invoke"
                Parameters = {
                  FunctionName = aws_lambda_function.avro_transformer.arn
                  Payload = {
                    "event.$" = "$.enriched.Payload"
                  }
                }
                End = true
              }
            }
          },
          {
            StartAt = "TransformToProtobuf"
            States = {
              TransformToProtobuf = {
                Type     = "Task"
                Resource = "arn:aws:states:::lambda:invoke"
                Parameters = {
                  FunctionName = aws_lambda_function.protobuf_transformer.arn
                  Payload = {
                    "event.$" = "$.enriched.Payload"
                  }
                }
                End = true
              }
            }
          },
          {
            StartAt = "TransformToJSON"
            States = {
              TransformToJSON = {
                Type     = "Task"
                Resource = "arn:aws:states:::lambda:invoke"
                Parameters = {
                  FunctionName = aws_lambda_function.json_transformer.arn
                  Payload = {
                    "event.$" = "$.enriched.Payload"
                  }
                }
                End = true
              }
            }
          }
        ]
        ResultPath = "$.transformed"
        Catch = [
          {
            ErrorEquals = ["States.ALL"]
            ResultPath  = "$.error"
            Next        = "TransformationFailed"
          }
        ]
        Next = "PublishToKafka"
      }

      # Step 5: Publish Transformed Events to Kafka
      PublishToKafka = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.kafka_publisher.arn
          Payload = {
            "transformed.$" = "$.transformed"
          }
        }
        ResultPath = "$.publish"
        Retry = [
          {
            ErrorEquals     = ["Lambda.ServiceException", "Lambda.AWSLambdaException"]
            IntervalSeconds = 2
            MaxAttempts     = 5
            BackoffRate     = 2.0
          }
        ]
        Catch = [
          {
            ErrorEquals = ["States.ALL"]
            ResultPath  = "$.error"
            Next        = "PublishFailed"
          }
        ]
        Next = "UpdateMetrics"
      }

      # Step 6: Update CloudWatch Metrics
      UpdateMetrics = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.metrics_updater.arn
          Payload = {
            "status"      = "success"
            "event_type" = "$.event.event_type"
          }
        }
        ResultPath = "$.metrics"
        Next       = "TransformationComplete"
      }

      # Success State
      TransformationComplete = {
        Type = "Succeed"
      }

      # Error States
      ValidationFailed = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.dlq_handler.arn
          Payload = {
            "error_type" = "validation_failed"
            "event.$"    = "$"
          }
        }
        Next = "TransformationFailed"
      }

      EnrichmentFailed = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.dlq_handler.arn
          Payload = {
            "error_type" = "enrichment_failed"
            "event.$"    = "$"
          }
        }
        Next = "TransformationFailed"
      }

      TransformationFailed = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.dlq_handler.arn
          Payload = {
            "error_type" = "transformation_failed"
            "event.$"    = "$"
          }
        }
        Next = "Failed"
      }

      PublishFailed = {
        Type     = "Task"
        Resource = "arn:aws:states:::lambda:invoke"
        Parameters = {
          FunctionName = aws_lambda_function.dlq_handler.arn
          Payload = {
            "error_type" = "publish_failed"
            "event.$"    = "$"
          }
        }
        Next = "Failed"
      }

      Failed = {
        Type = "Fail"
        Cause = "Event transformation workflow failed"
      }
    }
  })

  # Logging configuration
  logging_configuration {
    log_destination        = "${aws_cloudwatch_log_group.step_functions.arn}:*"
    include_execution_data = true
    level                  = "ALL"
  }

  tags = merge(var.common_tags, {
    Name      = "eaas-transformation-workflow-${var.environment}"
    Component = "transformation"
  })
}

# IAM Role for Step Functions
resource "aws_iam_role" "step_functions" {
  name = "eaas-step-functions-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

# IAM Policy for Step Functions
resource "aws_iam_role_policy" "step_functions" {
  name = "step-functions-policy"
  role = aws_iam_role.step_functions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = [
          aws_lambda_function.schema_validator.arn,
          aws_lambda_function.event_enricher.arn,
          aws_lambda_function.avro_transformer.arn,
          aws_lambda_function.protobuf_transformer.arn,
          aws_lambda_function.json_transformer.arn,
          aws_lambda_function.kafka_publisher.arn,
          aws_lambda_function.metrics_updater.arn,
          aws_lambda_function.dlq_handler.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "xray:PutTraceSegments",
          "xray:PutTelemetryRecords"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogDelivery",
          "logs:GetLogDelivery",
          "logs:UpdateLogDelivery",
          "logs:DeleteLogDelivery",
          "logs:ListLogDeliveries",
          "logs:PutResourcePolicy",
          "logs:DescribeResourcePolicies",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

# CloudWatch Log Group for Step Functions
resource "aws_cloudwatch_log_group" "step_functions" {
  name              = "/aws/stepfunctions/eaas-transformation-workflow-${var.environment}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.logs.arn

  tags = var.common_tags
}

# EventBridge Rule to Trigger Step Functions (Optional)
resource "aws_cloudwatch_event_rule" "trigger_transformation" {
  name                = "eaas-trigger-transformation-${var.environment}"
  description         = "Trigger transformation workflow on new events"
  schedule_expression = "rate(5 minutes)"

  tags = var.common_tags
}

resource "aws_cloudwatch_event_target" "step_functions" {
  rule      = aws_cloudwatch_event_rule.trigger_transformation.name
  target_id = "StepFunctionsTarget"
  arn       = aws_sfn_state_machine.event_transformation_workflow.arn
  role_arn  = aws_iam_role.eventbridge_trigger.arn
}

# IAM Role for EventBridge to Trigger Step Functions
resource "aws_iam_role" "eventbridge_trigger" {
  name = "eaas-eventbridge-trigger-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy" "eventbridge_trigger" {
  name = "eventbridge-trigger-policy"
  role = aws_iam_role.eventbridge_trigger.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = aws_sfn_state_machine.event_transformation_workflow.arn
      }
    ]
  })
}
```

