#### REQ-IFR-INT-003-006: Transformation Error Handling and DLQ

**Status**: Recommended
**Rationale**: Handle transformation failures without data loss

**Requirements**:
- Configure Dead Letter Queue (DLQ) for all transformation services
- Publish failed transformations with error details and original payload
- Implement retry logic with exponential backoff
- Configure DLQ monitoring and alerting
- Define DLQ message retention and investigation procedures

**Implementation**:
```hcl
# Kafka DLQ Topic for Failed Transformations
resource "aws_msk_topic" "transformation_dlq" {
  cluster_arn = module.msk_cluster.arn
  topic_name  = "eaas.transformation.dlq"

  topic_config {
    partitions     = 12
    replication_factor = 3

    configs = {
      "retention.ms"           = "1209600000"  # 14 days
      "cleanup.policy"         = "delete"
      "compression.type"       = "gzip"
      "max.message.bytes"      = "10485760"  # 10MB
      "min.insync.replicas"    = "2"
    }
  }
}

# SQS DLQ for Lambda Functions
resource "aws_sqs_queue" "transformation_dlq" {
  name                      = "eaas-transformation-dlq-${var.environment}"
  message_retention_seconds = 1209600  # 14 days
  visibility_timeout_seconds = 300

  # Enable encryption
  kms_master_key_id = aws_kms_key.sqs.id

  # Redrive policy not needed for DLQ itself

  tags = merge(var.common_tags, {
    Name      = "eaas-transformation-dlq-${var.environment}"
    Component = "transformation-dlq"
  })
}

# Lambda Function for DLQ Handler
resource "aws_lambda_function" "dlq_handler" {
  filename      = "dlq_handler.zip"
  function_name = "eaas-dlq-handler-${var.environment}"
  role          = aws_iam_role.dlq_handler.arn
  handler       = "index.handler"
  runtime       = "python3.12"
  timeout       = 30
  memory_size   = 256

  environment {
    variables = {
      DLQ_KAFKA_TOPIC     = "eaas.transformation.dlq"
      DLQ_SQS_QUEUE_URL   = aws_sqs_queue.transformation_dlq.url
      KAFKA_BROKERS       = module.msk_cluster.bootstrap_brokers_tls
      NOTIFICATION_SNS    = aws_sns_topic.dlq_alerts.arn
    }
  }

  vpc_config {
    subnet_ids         = var.private_subnet_ids
    security_group_ids = [aws_security_group.dlq_handler.id]
  }

  tags = merge(var.common_tags, {
    Name      = "eaas-dlq-handler-${var.environment}"
    Component = "transformation-dlq"
  })
}

# IAM Role for DLQ Handler
resource "aws_iam_role" "dlq_handler" {
  name = "eaas-dlq-handler-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy" "dlq_handler" {
  name = "dlq-handler-policy"
  role = aws_iam_role.dlq_handler.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sqs:SendMessage",
          "sqs:GetQueueUrl"
        ]
        Resource = aws_sqs_queue.transformation_dlq.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:WriteData"
        ]
        Resource = module.msk_cluster.arn
      },
      {
        Effect = "Allow"
        Action = [
          "sns:Publish"
        ]
        Resource = aws_sns_topic.dlq_alerts.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Resource = "*"
      }
    ]
  })
}

# SNS Topic for DLQ Alerts
resource "aws_sns_topic" "dlq_alerts" {
  name              = "eaas-transformation-dlq-alerts-${var.environment}"
  kms_master_key_id = aws_kms_key.sns.id

  tags = var.common_tags
}

resource "aws_sns_topic_subscription" "dlq_alerts_email" {
  topic_arn = aws_sns_topic.dlq_alerts.arn
  protocol  = "email"
  endpoint  = var.dlq_alert_email
}

# CloudWatch Alarms for DLQ
resource "aws_cloudwatch_metric_alarm" "dlq_messages" {
  alarm_name          = "eaas-transformation-dlq-messages-${var.environment}"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "2"
  metric_name         = "ApproximateNumberOfMessagesVisible"
  namespace           = "AWS/SQS"
  period              = "300"
  statistic           = "Average"
  threshold           = "10"
  alarm_description   = "Alert when DLQ has more than 10 messages"
  alarm_actions       = [aws_sns_topic.dlq_alerts.arn]

  dimensions = {
    QueueName = aws_sqs_queue.transformation_dlq.name
  }

  tags = var.common_tags
}

resource "aws_cloudwatch_metric_alarm" "dlq_age" {
  alarm_name          = "eaas-transformation-dlq-message-age-${var.environment}"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "ApproximateAgeOfOldestMessage"
  namespace           = "AWS/SQS"
  period              = "300"
  statistic           = "Maximum"
  threshold           = "3600"  # 1 hour in seconds
  alarm_description   = "Alert when DLQ has messages older than 1 hour"
  alarm_actions       = [aws_sns_topic.dlq_alerts.arn]

  dimensions = {
    QueueName = aws_sqs_queue.transformation_dlq.name
  }

  tags = var.common_tags
}

# Security Group for DLQ Handler
resource "aws_security_group" "dlq_handler" {
  name_prefix = "eaas-dlq-handler-${var.environment}-"
  description = "Security group for DLQ handler Lambda"
  vpc_id      = var.vpc_id

  egress {
    description = "MSK access"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "HTTPS for SQS/SNS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.common_tags, {
    Name = "eaas-dlq-handler-${var.environment}"
  })
}
```

