### Kafka Streams Application Template

```java
// Kafka Streams Application for Event Transformation
// File: src/main/java/com/eaas/transformation/EventTransformerApp.java

package com.eaas.transformation;

import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.KafkaStreams;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.kstream.*;
import org.apache.kafka.streams.state.Stores;
import io.confluent.kafka.serializers.AbstractKafkaSchemaSerDeConfig;
import io.confluent.kafka.streams.serdes.avro.SpecificAvroSerde;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.Duration;
import java.util.Properties;
import java.util.concurrent.CountDownLatch;

public class EventTransformerApp {
    private static final Logger logger = LoggerFactory.getLogger(EventTransformerApp.class);

    private static final String INPUT_TOPIC = "eaas.raw.events";
    private static final String OUTPUT_TOPIC = "eaas.transformed.events";
    private static final String STATE_STORE_NAME = "transformation-state-store";

    public static void main(String[] args) {
        Properties props = getStreamsConfig();

        StreamsBuilder builder = new StreamsBuilder();
        buildTopology(builder);

        KafkaStreams streams = new KafkaStreams(builder.build(), props);

        // Graceful shutdown hook
        CountDownLatch latch = new CountDownLatch(1);
        Runtime.getRuntime().addShutdownHook(new Thread("streams-shutdown-hook") {
            @Override
            public void run() {
                logger.info("Shutting down Kafka Streams application...");
                streams.close(Duration.ofSeconds(30));
                latch.countDown();
            }
        });

        try {
            streams.start();
            logger.info("Kafka Streams application started successfully");
            latch.await();
        } catch (Throwable e) {
            logger.error("Kafka Streams application error", e);
            System.exit(1);
        }

        System.exit(0);
    }

    private static Properties getStreamsConfig() {
        Properties props = new Properties();

        // Application configuration
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "eaas-streams-transformer-prod");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, System.getenv("KAFKA_BOOTSTRAP_SERVERS"));

        // Processing guarantees
        props.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG, StreamsConfig.EXACTLY_ONCE_V2);

        // Serialization
        props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, SpecificAvroSerde.class);

        // Schema Registry
        props.put(AbstractKafkaSchemaSerDeConfig.SCHEMA_REGISTRY_URL_CONFIG,
                  System.getenv("SCHEMA_REGISTRY_URL"));

        // Performance tuning
        props.put(StreamsConfig.NUM_STREAM_THREADS_CONFIG, 4);
        props.put(StreamsConfig.NUM_STANDBY_REPLICAS_CONFIG, 1);
        props.put(StreamsConfig.CACHE_MAX_BYTES_BUFFERING_CONFIG, 10 * 1024 * 1024);
        props.put(StreamsConfig.COMMIT_INTERVAL_MS_CONFIG, 1000);

        // State store directory
        props.put(StreamsConfig.STATE_DIR_CONFIG, System.getenv("STATE_STORE_DIR"));

        // Error handling
        props.put(StreamsConfig.DEFAULT_DESERIALIZATION_EXCEPTION_HANDLER_CLASS_CONFIG,
                  LogAndContinueExceptionHandler.class);
        props.put(StreamsConfig.DEFAULT_PRODUCTION_EXCEPTION_HANDLER_CLASS_CONFIG,
                  DefaultProductionExceptionHandler.class);

        return props;
    }

    private static void buildTopology(StreamsBuilder builder) {
        // Create state store for enrichment data
        builder.addStateStore(
            Stores.keyValueStoreBuilder(
                Stores.persistentKeyValueStore(STATE_STORE_NAME),
                Serdes.String(),
                Serdes.String()
            )
        );

        // Input stream
        KStream<String, RawEvent> rawEvents = builder.stream(
            INPUT_TOPIC,
            Consumed.with(Serdes.String(), new SpecificAvroSerde<RawEvent>())
        );

        // Transformation pipeline
        KStream<String, TransformedEvent> transformedEvents = rawEvents
            // Filter invalid events
            .filter((key, value) -> value != null && value.getEventType() != null)

            // Map to transformed structure
            .mapValues((readOnlyKey, value) -> {
                logger.debug("Transforming event: {}", value.getEventId());
                return transformEvent(value);
            })

            // Enrich with state store data
            .transformValues(() -> new EnrichmentTransformer(STATE_STORE_NAME), STATE_STORE_NAME)

            // Branch by event type
            .branch(
                (key, value) -> "ORDER".equals(value.getEventType()),
                (key, value) -> "PAYMENT".equals(value.getEventType()),
                (key, value) -> true  // catch-all
            )[0]  // Process ORDER events

            // Aggregate by time window (example)
            .groupByKey()
            .windowedBy(TimeWindows.of(Duration.ofMinutes(5)))
            .aggregate(
                TransformedEvent::new,
                (key, value, aggregate) -> aggregate,
                Materialized.with(Serdes.String(), new SpecificAvroSerde<TransformedEvent>())
            )
            .toStream()
            .map((windowedKey, value) -> KeyValue.pair(windowedKey.key(), value));

        // Write to output topic
        transformedEvents.to(
            OUTPUT_TOPIC,
            Produced.with(Serdes.String(), new SpecificAvroSerde<TransformedEvent>())
        );

        // Error handling: send failed records to DLQ
        rawEvents
            .filter((key, value) -> value == null)
            .to("eaas.transformation.dlq");
    }

    private static TransformedEvent transformEvent(RawEvent rawEvent) {
        // Transformation logic
        return TransformedEvent.newBuilder()
            .setEventId(rawEvent.getEventId())
            .setEventType(rawEvent.getEventType())
            .setTimestamp(System.currentTimeMillis())
            .setPayload(normalizePayload(rawEvent.getPayload()))
            .setMetadata(buildMetadata())
            .build();
    }

    private static String normalizePayload(String payload) {
        // Normalization logic
        return payload;
    }

    private static Map<String, String> buildMetadata() {
        Map<String, String> metadata = new HashMap<>();
        metadata.put("transformed_at", String.valueOf(System.currentTimeMillis()));
        metadata.put("transformation_version", "1.0");
        return metadata;
    }
}
