{
  "Comment": "Complete event transformation workflow with validation, enrichment, transformation, and delivery",
  "StartAt": "ValidateEvent",
  "States": {
    "ValidateEvent": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${SchemaValidatorFunctionArn}",
        "Payload": {
          "event.$": "$"
        }
      },
      "ResultPath": "$.validation",
      "Retry": [
        {
          "ErrorEquals": ["Lambda.ServiceException", "Lambda.AWSLambdaException", "Lambda.SdkClientException"],
          "IntervalSeconds": 2,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.error",
          "Next": "ValidationFailed"
        }
      ],
      "Next": "CheckValidation"
    },
    "CheckValidation": {
      "Type": "Choice",
      "Choices": [
        {
          "Variable": "$.validation.Payload.valid",
          "BooleanEquals": true,
          "Next": "EnrichEvent"
        }
      ],
      "Default": "ValidationFailed"
    },
    "EnrichEvent": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${EventEnricherFunctionArn}",
        "Payload": {
          "event.$": "$.event"
        }
      },
      "ResultPath": "$.enriched",
      "Retry": [
        {
          "ErrorEquals": ["Lambda.ServiceException"],
          "IntervalSeconds": 2,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.error",
          "Next": "EnrichmentFailed"
        }
      ],
      "Next": "TransformParallel"
    },
    "TransformParallel": {
      "Type": "Parallel",
      "Branches": [
        {
          "StartAt": "TransformAvro",
          "States": {
            "TransformAvro": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${AvroTransformerFunctionArn}",
                "Payload.$": "$.enriched.Payload"
              },
              "End": true
            }
          }
        },
        {
          "StartAt": "TransformProtobuf",
          "States": {
            "TransformProtobuf": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${ProtobufTransformerFunctionArn}",
                "Payload.$": "$.enriched.Payload"
              },
              "End": true
            }
          }
        },
        {
          "StartAt": "TransformJSON",
          "States": {
            "TransformJSON": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${JSONTransformerFunctionArn}",
                "Payload.$": "$.enriched.Payload"
              },
              "End": true
            }
          }
        }
      ],
      "ResultPath": "$.transformed",
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.error",
          "Next": "TransformationFailed"
        }
      ],
      "Next": "PublishToKafka"
    },
    "PublishToKafka": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${KafkaPublisherFunctionArn}",
        "Payload": {
          "transformed.$": "$.transformed"
        }
      },
      "ResultPath": "$.publish",
      "Retry": [
        {
          "ErrorEquals": ["Lambda.ServiceException"],
          "IntervalSeconds": 2,
          "MaxAttempts": 5,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.error",
          "Next": "PublishFailed"
        }
      ],
      "Next": "UpdateMetrics"
    },
    "UpdateMetrics": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${MetricsUpdaterFunctionArn}",
        "Payload": {
          "status": "success",
          "event_type.$": "$.event.event_type"
        }
      },
      "ResultPath": "$.metrics",
      "Next": "TransformationComplete"
    },
    "TransformationComplete": {
      "Type": "Succeed"
    },
    "ValidationFailed": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${DLQHandlerFunctionArn}",
        "Payload": {
          "error_type": "validation_failed",
          "event.$": "$"
        }
      },
      "Next": "TransformationFailed"
    },
    "EnrichmentFailed": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${DLQHandlerFunctionArn}",
        "Payload": {
          "error_type": "enrichment_failed",
          "event.$": "$"
        }
      },
      "Next": "TransformationFailed"
    },
    "TransformationFailed": {
      "Type": "Fail",
      "Cause": "Event transformation failed",
      "Error": "TransformationError"
    },
    "PublishFailed": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "${DLQHandlerFunctionArn}",
        "Payload": {
          "error_type": "publish_failed",
          "event.$": "$"
        }
      },
      "Next": "TransformationFailed"
    }
  }
}
